const input1 = document.getElementById("userInput1");
const donebtn = document.querySelector(".done-btn");
const rem = document.getElementById("rem");
const final = document.getElementById("final");
const i = document.getElementById("i");
var flag = 0;
input1.value = 11;
final.value = "prime";
i.value = "2";
rem.disabled = true;
final.disabled = true;
i.disabled = true;
donebtn.addEventListener("click", function(){
    if(flag == 0){
        show();
    }else{
        init();
    }

});
function init(){
  input1.style.background = "#F8F8F8";
  donebtn.innerHTML = "Done";
  flag = 0;
  input1.disabled = false;
  input1.value = 11;
  rem.value = "";
  i.value = "2";
  final.value = "prime";
}
function show(){
    donebtn.disabled = true;
    donebtn.style.visibility = "hidden";
    input1.disabled = true;
    var t = input1.value;
    if(t.indexOf('.') !== -1 || isNaN(parseInt(t)) || parseInt(t) < 4 || parseInt(t) > 100) {
    input1.style.background = "red";
    donebtn.innerHTML = "Reset";
    flag = 1;
    donebtn.disabled = false;
    donebtn.style.visibility = "visible";
    }else{
    var inp = parseInt(input1.value);
    var check = Math.trunc(inp / 2);
    var ii = 2;
    var f = 0;
  // store the interval id to clear in future
    var intr = setInterval(function() {
    var rem2 = inp % ii;
    //rem.style.background = "#FFCC00";
    rem.value = rem2.toString();
    if (rem2 == 0){
      //final.style.background = "#FFCC00";
      final.value = "not prime";
      f = 1;
    }
    //i.style.background = "#FFCC00";
    i.value = ii.toString();
    ii = ii + 1;
    // setTimeout(function(){
    //   rem.style.background = "#F8F8F8";
    //   final.style.background = "#F8F8F8";
    //   i.style.background = "#F8F8F8";
    // }, 1000);

    // clear the interval if `i` reached 100
    if (ii == (check + 1) || f == 1) {
      clearInterval(intr);
      //console.log("Done");
      donebtn.innerHTML = "Reset";
      donebtn.disabled = false;
      donebtn.style.visibility = "visible";
      flag = 1;
    }
    }, 2000)
    }
    
}
